"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["54622"],{73546(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_do_fada.fato_elegibilidade_invalido","status":422,"titulo":"O c\xf3digo do fato de elegibilidade do acr\xe9scimo \xe9 inv\xe1lido"},"descricao":{"codigo":"uniplus.selecao.configuracao_do_fada.fato_elegibilidade_invalido","requisitos":[],"oQueAconteceu":["A declara\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso (FADA) citou, em\\n`fatoElegibilidadeCodigo`, um c\xf3digo de dado de elegibilidade fora do formato aceito. O dado de\\nelegibilidade \xe9 o dado do candidato que decide quem recebe o acr\xe9scimo; a cita\xe7\xe3o \xe9 opcional\\nneste ponto, mas, quando feita, o c\xf3digo \xe9 conferido exatamente como foi enviado e precisa seguir estas regras:","- come\xe7ar com letra mai\xfascula de A a Z;\\n- ter, depois da primeira letra, s\xf3 letras mai\xfasculas sem acento e d\xedgitos;\\n- usar o sublinhado s\xf3 para separar partes, nunca no fim do c\xf3digo nem duas vezes seguidas;\\n- ter no m\xe1ximo 50 caracteres.","Os espa\xe7os no come\xe7o ou no fim do c\xf3digo n\xe3o s\xe3o retirados e fazem a declara\xe7\xe3o ser recusada.\\nTexto vazio ou s\xf3 com espa\xe7os tamb\xe9m \xe9 recusado, porque n\xe3o tem o formato. Por exemplo,\\n`DECLARACAO_RESIDENTE_MARABA` \xe9 aceito; `declaracao_residente` (min\xfasculas), `1_DECLARACAO`\\n(come\xe7a com d\xedgito) e `DECLARACAO__RESIDENTE` (sublinhado duplicado) s\xe3o recusados.","Esta recusa confere s\xf3 a forma do c\xf3digo. Se o dado do candidato \xe9 do processo e se \xe9 do tipo\\nverdadeiro ou falso s\xe3o confer\xeancias separadas, com outros c\xf3digos de erro.","A recusa vem no campo `fatoElegibilidadeCodigo` e acumula, na mesma resposta, com as demais\\nviola\xe7\xf5es dos valores do fator, em\\n[`fator_invalido`](/erros/uniplus.selecao.configuracao_do_fada.fator_invalido) e\\n[`teto_invalido`](/erros/uniplus.selecao.configuracao_do_fada.teto_invalido).\\nEla vem depois da confer\xeancia da regra e da base legal; se alguma delas falhar, os valores\\nnem chegam a ser conferidos.","Esta mesma confer\xeancia tamb\xe9m roda quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada, na retifica\xe7\xe3o em ato \xfanico. Nesse caso a recusa sai como uma viola\xe7\xe3o \xfanica (sem a lista `errors[]`) e se\\nrefere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Na declara\xe7\xe3o, informe o c\xf3digo exato do dado do candidato do processo que decide quem recebe o\\nacr\xe9scimo, sem espa\xe7os no come\xe7o nem no fim: letra mai\xfascula inicial, depois s\xf3 letras\\nmai\xfasculas e d\xedgitos, com sublinhado apenas separando partes, e at\xe9 50 caracteres (por exemplo,\\n`DECLARACAO_RESIDENTE_MARABA`). Ou omita o campo.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a\\nconfigura\xe7\xe3o congelada da vers\xe3o publicada, e regravar a configura\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Declara\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao do fada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);